#include <stdio.h>

int findKthNumber(int m, int n, int k) {
    int a = m < n ? m : n;
    int b = m > n ? m : n;
    long long left = 1, right = (long long)m * n;

    while (left < right) {
        long long mid = left + (right - left) / 2;
        long long count = 0;

        for (int i = 1; i <= a; ++i) {
            long long v = mid / i;
            count += v < b ? v : b;
            if (count >= k) break;
        }

        if (count >= k) right = mid;
        else left = mid + 1;
    }
    return (int)left;
}

