function findKthNumber(m, n, k) {
    const a = Math.min(m, n);
    const b = Math.max(m, n);
    let left = 1;
    let right = m * n;

    while (left < right) {
        const mid = Math.floor(left + (right - left) / 2);
        let count = 0;

        for (let i = 1; i <= a; i++) {
            count += Math.min(Math.floor(mid / i), b);
            if (count >= k) break;
        }

        if (count >= k) right = mid;
        else left = mid + 1;
    }
    return left;
